     1→import { BaseSidebarLayout } from "../_navigation/base-sidebar-layout";
     2→import type { PropsWithChildren } from "react";
     3→import { TradingSidebar } from "./_navigation/trading-sidebar";
     4→import { getRequiredUser } from "@/lib/auth/auth-user";
     5→import { checkUserHasTraderProfile } from "@/features/trader/trader-queries";
     6→import { getAllNavigationLinks } from "../_navigation/navigation-helpers";
     7→import { countFollowedTraders } from "@/features/follow/follow-queries";
     8→import type { MyCryptoPilotPlanName } from "@/lib/crypto/mycryptopilot-plans";
     9→
    10→/**
    11→ * Trading Layout
    12→ *
    13→ * Issue #81 - Réorganisation sidebar Trading:
    14→ * - Nouvelle structure par intention (MY FEED, DISCOVER, MY TRADING, PUBLISH, INSIGHTS & GROWTH)
    15→ * - Badges dynamiques selon plan utilisateur
    16→ * - Compteur de signaux actifs suivis
    17→ * - État des sections persiste dans localStorage
    18→ *
    19→ * Layout pour l'espace Trading avec sidebar dédiée
    20→ * Contient: Dashboard, Signals, Traders, Pricing, Checkout
    21→ * Sidebar conditionnelle selon le rôle (trader ou consumer)
    22→ */
    23→export default async function TradingLayout({ children }: PropsWithChildren) {
    24→  const user = await getRequiredUser();
    25→
    26→  // Check if user has trader profile (for conditional PUBLISH section)
    27→  const hasTraderProfile = await checkUserHasTraderProfile(user.id);
    28→
    29→  // Get user plan for badges
    30→  const userPlan = (user.planName ?? "free") as MyCryptoPilotPlanName;
    31→
    32→  // Count active follows (for badge on Following)
    33→  const activeSignalsCount = await countFollowedTraders(user.id);
    34→
    35→  // Get all links for global search (from all 4 spaces)
    36→  const allLinks = getAllNavigationLinks(hasTraderProfile);
    37→
    38→  return (
    39→    <BaseSidebarLayout
    40→      sidebar={
    41→        <TradingSidebar
    42→          allLinks={allLinks}
    43→          hasTraderProfile={hasTraderProfile}
    44→          activeSignalsCount={activeSignalsCount}
    45→          userPlan={userPlan}
    46→        />
    47→      }
    48→    >
    49→      {children}
    50→    </BaseSidebarLayout>
    51→  );
    52→}
