     1→"use client";
     2→
     3→import { Slot } from "@radix-ui/react-slot";
     4→import type { VariantProps } from "class-variance-authority";
     5→import { cva } from "class-variance-authority";
     6→import { PanelLeftIcon } from "lucide-react";
     7→import * as React from "react";
     8→
     9→import { Button } from "@/components/ui/button";
    10→import { Input } from "@/components/ui/input";
    11→import { Separator } from "@/components/ui/separator";
    12→import {
    13→  Sheet,
    14→  SheetContent,
    15→  SheetDescription,
    16→  SheetHeader,
    17→  SheetTitle,
    18→} from "@/components/ui/sheet";
    19→import { Skeleton } from "@/components/ui/skeleton";
    20→import {
    21→  Tooltip,
    22→  TooltipContent,
    23→  TooltipProvider,
    24→  TooltipTrigger,
    25→} from "@/components/ui/tooltip";
    26→import { useIsMobile } from "@/hooks/use-mobile";
    27→import { cn } from "@/lib/utils";
    28→
    29→const SIDEBAR_COOKIE_NAME = "sidebar_state";
    30→const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;
    31→const SIDEBAR_WIDTH = "16rem";
    32→const SIDEBAR_WIDTH_MOBILE = "18rem";
    33→const SIDEBAR_WIDTH_ICON = "3rem";
    34→const SIDEBAR_KEYBOARD_SHORTCUT = "b";
    35→
    36→type SidebarContextProps = {
    37→  state: "expanded" | "collapsed";
    38→  open: boolean;
    39→  setOpen: (open: boolean) => void;
    40→  openMobile: boolean;
    41→  setOpenMobile: (open: boolean) => void;
    42→  isMobile: boolean;
    43→  toggleSidebar: () => void;
    44→};
    45→
    46→const SidebarContext = React.createContext<SidebarContextProps | null>(null);
    47→
    48→function useSidebar() {
    49→  const context = React.useContext(SidebarContext);
    50→  if (!context) {
    51→    throw new Error("useSidebar must be used within a SidebarProvider.");
    52→  }
    53→
    54→  return context;
    55→}
    56→
    57→function SidebarProvider({
    58→  defaultOpen = true,
    59→  open: openProp,
    60→  onOpenChange: setOpenProp,
    61→  className,
    62→  style,
    63→  children,
    64→  ...props
    65→}: React.ComponentProps<"div"> & {
    66→  defaultOpen?: boolean;
    67→  open?: boolean;
    68→  onOpenChange?: (open: boolean) => void;
    69→}) {
    70→  const isMobile = useIsMobile();
    71→  const [openMobile, setOpenMobile] = React.useState(false);
    72→
    73→  // This is the internal state of the sidebar.
    74→  // We use openProp and setOpenProp for control from outside the component.
    75→  const [_open, _setOpen] = React.useState(defaultOpen);
    76→  const open = openProp ?? _open;
    77→
    78→  const setOpen = React.useCallback(
    79→    (value: boolean | ((value: boolean) => boolean)) => {
    80→      const openState = typeof value === "function" ? value(open) : value;
    81→      if (setOpenProp) {
    82→        setOpenProp(openState);
    83→      } else {
    84→        _setOpen(openState);
    85→      }
    86→
    87→      // This sets the cookie to keep the sidebar state.
    88→      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
    89→    },
    90→    [setOpenProp, open],
    91→  );
    92→
    93→  // Helper to toggle the sidebar.
    94→  const toggleSidebar = React.useCallback(() => {
    95→    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
    96→  }, [isMobile, setOpen, setOpenMobile]);
    97→
    98→  // Adds a keyboard shortcut to toggle the sidebar.
    99→  React.useEffect(() => {
   100→    const handleKeyDown = (event: KeyboardEvent) => {
   101→      if (
   102→        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
   103→        (event.metaKey || event.ctrlKey)
   104→      ) {
   105→        event.preventDefault();
   106→        toggleSidebar();
   107→      }
   108→    };
   109→
   110→    window.addEventListener("keydown", handleKeyDown);
   111→    return () => window.removeEventListener("keydown", handleKeyDown);
   112→  }, [toggleSidebar]);
   113→
   114→  // Initialize sidebar state from cookie when component mounts
   115→  React.useEffect(() => {
   116→    // Only run on client-side
   117→    if (typeof document !== "undefined") {
   118→      const cookies = document.cookie.split(";");
   119→      const sidebarCookie = cookies.find((cookie) =>
   120→        cookie.trim().startsWith(`${SIDEBAR_COOKIE_NAME}=`),
   121→      );
   122→
   123→      if (sidebarCookie) {
   124→        const cookieValue = sidebarCookie.split("=")[1];
   125→        const isOpen = cookieValue === "true";
   126→
   127→        // Only update if we're not controlled externally
   128→        if (setOpenProp === undefined) {
   129→          _setOpen(isOpen);
   130→        }
   131→      }
   132→    }
   133→  }, [setOpenProp]);
   134→
   135→  // We add a state so that we can do data-state="expanded" or "collapsed".
   136→  // This makes it easier to style the sidebar with Tailwind classes.
   137→  const state = open ? "expanded" : "collapsed";
   138→
   139→  const contextValue = React.useMemo<SidebarContextProps>(
   140→    () => ({
   141→      state,
   142→      open,
   143→      setOpen,
   144→      isMobile,
   145→      openMobile,
   146→      setOpenMobile,
   147→      toggleSidebar,
   148→    }),
   149→    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar],
   150→  );
   151→
   152→  return (
   153→    <SidebarContext.Provider value={contextValue}>
   154→      <TooltipProvider delayDuration={0}>
   155→        <div
   156→          data-slot="sidebar-wrapper"
   157→          style={
   158→            {
   159→              "--sidebar-width": SIDEBAR_WIDTH,
   160→              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
   161→              ...style,
   162→            } as React.CSSProperties
   163→          }
   164→          className={cn(
   165→            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
   166→            className,
   167→          )}
   168→          {...props}
   169→        >
   170→          {children}
   171→        </div>
   172→      </TooltipProvider>
   173→    </SidebarContext.Provider>
   174→  );
   175→}
   176→
   177→function Sidebar({
   178→  side = "left",
   179→  variant = "sidebar",
   180→  collapsible = "offcanvas",
   181→  className,
   182→  children,
   183→  ...props
   184→}: React.ComponentProps<"div"> & {
   185→  side?: "left" | "right";
   186→  variant?: "sidebar" | "floating" | "inset";
   187→  collapsible?: "offcanvas" | "icon" | "none";
   188→}) {
   189→  const { isMobile, state, openMobile, setOpenMobile } = useSidebar();
   190→
   191→  if (collapsible === "none") {
   192→    return (
   193→      <div
   194→        data-slot="sidebar"
   195→        className={cn(
   196→          "bg-sidebar text-sidebar-foreground flex h-full w-(--sidebar-width) flex-col",
   197→          className,
   198→        )}
   199→        {...props}
   200→      >
   201→        {children}
   202→      </div>
   203→    );
   204→  }
   205→
   206→  if (isMobile) {
   207→    return (
   208→      <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
   209→        <SheetContent
   210→          data-sidebar="sidebar"
   211→          data-slot="sidebar"
   212→          data-mobile="true"
   213→          className="bg-sidebar text-sidebar-foreground w-(--sidebar-width) p-0 [&>button]:hidden"
   214→          style={
   215→            {
   216→              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
   217→            } as React.CSSProperties
   218→          }
   219→          side={side}
   220→        >
   221→          <SheetHeader className="sr-only">
   222→            <SheetTitle>Sidebar</SheetTitle>
   223→            <SheetDescription>Displays the mobile sidebar.</SheetDescription>
   224→          </SheetHeader>
   225→          <div className="flex size-full flex-col">{children}</div>
   226→        </SheetContent>
   227→      </Sheet>
   228→    );
   229→  }
   230→
   231→  return (
   232→    <div
   233→      className="text-sidebar-foreground group peer hidden md:block"
   234→      data-state={state}
   235→      data-collapsible={state === "collapsed" ? collapsible : ""}
   236→      data-variant={variant}
   237→      data-side={side}
   238→      data-slot="sidebar"
   239→    >
   240→      {/* This is what handles the sidebar gap on desktop */}
   241→      <div
   242→        data-slot="sidebar-gap"
   243→        className={cn(
   244→          "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
   245→          "group-data-[collapsible=offcanvas]:w-0",
   246→          "group-data-[side=right]:rotate-180",
   247→          variant === "floating" || variant === "inset"
   248→            ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
   249→            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)",
   250→        )}
   251→      />
   252→      <div
   253→        data-slot="sidebar-container"
   254→        className={cn(
   255→          "fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear md:flex",
   256→          side === "left"
   257→            ? "left-0 group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)]"
   258→            : "right-0 group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)]",
   259→          // Adjust the padding for floating and inset variants.
   260→          variant === "floating" || variant === "inset"
   261→            ? "p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]"
   262→            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon) group-data-[side=left]:border-r group-data-[side=right]:border-l",
   263→          className,
   264→        )}
   265→        {...props}
   266→      >
   267→        <div
   268→          data-sidebar="sidebar"
   269→          data-slot="sidebar-inner"
   270→          className="bg-sidebar group-data-[variant=floating]:border-sidebar-border flex size-full flex-col group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:border group-data-[variant=floating]:shadow-sm"
   271→        >
   272→          {children}
   273→        </div>
   274→      </div>
   275→    </div>
   276→  );
   277→}
   278→
   279→function SidebarTrigger({
   280→  className,
   281→  onClick,
   282→  ...props
   283→}: React.ComponentProps<typeof Button>) {
   284→  const { toggleSidebar } = useSidebar();
   285→
   286→  return (
   287→    <Button
   288→      data-sidebar="trigger"
   289→      data-slot="sidebar-trigger"
   290→      variant="ghost"
   291→      size="icon"
   292→      className={cn("size-7", className)}
   293→      onClick={(event) => {
   294→        onClick?.(event);
   295→        toggleSidebar();
   296→      }}
   297→      {...props}
   298→    >
   299→      <PanelLeftIcon />
   300→      <span className="sr-only">Toggle Sidebar</span>
   301→    </Button>
   302→  );
   303→}
   304→
   305→function SidebarRail({ className, ...props }: React.ComponentProps<"button">) {
   306→  const { toggleSidebar } = useSidebar();
   307→
   308→  return (
   309→    <button
   310→      data-sidebar="rail"
   311→      data-slot="sidebar-rail"
   312→      aria-label="Toggle Sidebar"
   313→      tabIndex={-1}
   314→      onClick={toggleSidebar}
   315→      title="Toggle Sidebar"
   316→      className={cn(
   317→        "hover:after:bg-sidebar-border absolute inset-y-0 z-20 hidden w-4 -translate-x-1/2 transition-all ease-linear group-data-[side=left]:-right-4 group-data-[side=right]:left-0 after:absolute after:inset-y-0 after:left-1/2 after:w-[2px] sm:flex",
   318→        "in-data-[side=left]:cursor-w-resize in-data-[side=right]:cursor-e-resize",
   319→        "[[data-side=left][data-state=collapsed]_&]:cursor-e-resize [[data-side=right][data-state=collapsed]_&]:cursor-w-resize",
   320→        "hover:group-data-[collapsible=offcanvas]:bg-sidebar group-data-[collapsible=offcanvas]:translate-x-0 group-data-[collapsible=offcanvas]:after:left-full",
   321→        "[[data-side=left][data-collapsible=offcanvas]_&]:-right-2",
   322→        "[[data-side=right][data-collapsible=offcanvas]_&]:-left-2",
   323→        className,
   324→      )}
   325→      {...props}
   326→    />
   327→  );
   328→}
   329→
   330→function SidebarInset({ className, ...props }: React.ComponentProps<"main">) {
   331→  return (
   332→    <main
   333→      data-slot="sidebar-inset"
   334→      className={cn(
   335→        "bg-background relative flex w-full flex-1 flex-col",
   336→        "md:peer-data-[variant=inset]:m-2 md:peer-data-[variant=inset]:ml-0 md:peer-data-[variant=inset]:rounded-xl md:peer-data-[variant=inset]:shadow-sm md:peer-data-[variant=inset]:peer-data-[state=collapsed]:ml-2",
   337→        className,
   338→      )}
   339→      {...props}
   340→    />
   341→  );
   342→}
   343→
   344→function SidebarInput({
   345→  className,
   346→  ...props
   347→}: React.ComponentProps<typeof Input>) {
   348→  return (
   349→    <Input
   350→      data-slot="sidebar-input"
   351→      data-sidebar="input"
   352→      className={cn("bg-background h-8 w-full shadow-none", className)}
   353→      {...props}
   354→    />
   355→  );
   356→}
   357→
   358→function SidebarHeader({ className, ...props }: React.ComponentProps<"div">) {
   359→  return (
