     1→"use client";
     2→
     3→import {
     4→  Sidebar,
     5→  SidebarContent,
     6→  SidebarFooter,
     7→  SidebarGroup,
     8→  SidebarGroupContent,
     9→  SidebarGroupLabel,
    10→  SidebarHeader,
    11→  SidebarRail,
    12→  SidebarMenu,
    13→  SidebarMenuItem,
    14→} from "@/components/ui/sidebar";
    15→import { SidebarMenuButtonLink } from "@/components/ui/sidebar-utils";
    16→import { ContactFeedbackPopover } from "@/features/contact/feedback/contact-feedback-popover";
    17→import { SidebarUserButton } from "@/features/sidebar/sidebar-user-button";
    18→import { NavigationBadge } from "@/features/navigation/navigation-badge";
    19→import {
    20→  GlobalSearchCommand,
    21→  type SerializableGroup,
    22→} from "../../_navigation/global-search-command";
    23→import { getTradingNavigationGroups } from "./trading-links";
    24→import {
    25→  Collapsible,
    26→  CollapsibleContent,
    27→  CollapsibleTrigger,
    28→} from "@/components/ui/collapsible";
    29→import { ChevronDown } from "lucide-react";
    30→import { useSidebarState } from "@/stores/sidebar-state";
    31→import type { MyCryptoPilotPlanName } from "@/lib/crypto/mycryptopilot-plans";
    32→import { useEffect } from "react";
    33→import { cn } from "@/lib/utils";
    34→import { Skeleton } from "@/components/ui/skeleton";
    35→
    36→/**
    37→ * Trading Sidebar
    38→ *
    39→ * Issue #81 - Réorganisation sidebar Trading avec organisation par intention:
    40→ *
    41→ * Nouvelle structure (5 sections):
    42→ * - MY FEED: Dashboard + Following (engagement quotidien)
    43→ * - DISCOVER: Signals Feed + Traders Marketplace (découverte)
    44→ * - MY TRADING: My Trades + Risk Console + History (outils actifs)
    45→ * - PUBLISH: Trader Dashboard + Create Signal + Portfolio + Referral (traders uniquement)
    46→ * - INSIGHTS & GROWTH: Analytics + School + Tax + Upgrade (progression)
    47→ *
    48→ * Features:
    49→ * - Badges dynamiques (plan requirements, counts, status)
    50→ * - État des sections persiste dans localStorage (Zustand)
    51→ * - Sections collapsibles
    52→ * - Tooltips sur les badges locked
    53→ */
    54→export function TradingSidebar({
    55→  allLinks,
    56→  hasTraderProfile,
    57→  activeSignalsCount,
    58→  userPlan,
    59→}: {
    60→  allLinks: SerializableGroup[];
    61→  hasTraderProfile: boolean;
    62→  activeSignalsCount?: number;
    63→  userPlan?: MyCryptoPilotPlanName;
    64→}) {
    65→  // Get navigation groups avec données dynamiques
    66→  const navigationGroups = getTradingNavigationGroups(
    67→    hasTraderProfile,
    68→    activeSignalsCount,
    69→    userPlan,
    70→  );
    71→
    72→  // Utiliser store Zustand pour persister l'état collapsed/expanded
    73→  const collapsedSections = useSidebarState((state) => state.collapsedSections);
    74→  const toggleSection = useSidebarState((state) => state.toggleSection);
    75→  const hasHydrated = useSidebarState((state) => state.hasHydrated);
    76→
    77→  useEffect(() => {
    78→    if (!hasHydrated) {
    79→      void useSidebarState.persist.rehydrate();
    80→    }
    81→  }, [hasHydrated]);
    82→
    83→  if (!hasHydrated) {
    84→    return <SidebarLoadingState />;
    85→  }
    86→
    87→  return (
    88→    <Sidebar variant="inset" suppressHydrationWarning>
    89→      <SidebarHeader className="flex flex-col gap-2">
    90→        <GlobalSearchCommand allLinks={allLinks} />
    91→      </SidebarHeader>
    92→      <SidebarContent suppressHydrationWarning>
    93→        {navigationGroups.map((group) => {
    94→          const isOpen = !collapsedSections[group.title];
    95→
    96→          return (
    97→            <Collapsible
    98→              key={group.title}
    99→              open={isOpen}
   100→              onOpenChange={() => toggleSection(group.title)}
   101→              suppressHydrationWarning
   102→            >
   103→              <SidebarGroup suppressHydrationWarning>
   104→                <CollapsibleTrigger className="w-full [&[data-state=open]>div>svg]:rotate-180">
   105→                  <SidebarGroupLabel className="text-muted-foreground group/label hover:text-foreground flex w-full cursor-pointer items-center justify-between text-xs font-semibold tracking-wider uppercase transition-colors">
   106→                    <span className="flex items-center gap-2">
   107→                      {group.icon && <group.icon className="h-4 w-4" />}
   108→                      {group.title}
   109→                    </span>
   110→                    <div className="flex items-center gap-1">
   111→                      {group.badge && <NavigationBadge badge={group.badge} />}
   112→                      <ChevronDown
   113→                        className={cn(
   114→                          "size-4 transition-transform duration-200",
   115→                          isOpen && "rotate-180",
   116→                        )}
   117→                      />
   118→                    </div>
   119→                  </SidebarGroupLabel>
   120→                </CollapsibleTrigger>
   121→                <CollapsibleContent>
   122→                  <SidebarGroupContent>
   123→                    <SidebarMenu>
   124→                      {group.links.map((item) => {
   125→                        if (item.hidden) return null;
   126→
   127→                        return (
   128→                          <SidebarMenuItem key={item.label}>
   129→                            <SidebarMenuButtonLink href={item.href}>
   130→                              <item.Icon className="h-4 w-4" />
   131→                              <span>{item.label}</span>
   132→                              {item.badge && (
   133→                                <NavigationBadge badge={item.badge} />
   134→                              )}
   135→                            </SidebarMenuButtonLink>
   136→                          </SidebarMenuItem>
   137→                        );
   138→                      })}
   139→                    </SidebarMenu>
   140→                  </SidebarGroupContent>
   141→                </CollapsibleContent>
   142→              </SidebarGroup>
   143→            </Collapsible>
   144→          );
   145→        })}
   146→      </SidebarContent>
   147→      <SidebarFooter className="flex flex-col gap-2">
   148→        <ContactFeedbackPopover />
